"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.18356",title:"Urbex: Agentic Spatial Grounding for City-Scale 3D Scenes",up:57,href:"https://arxiv.org/abs/2610.18356",abstract:"City-scale 3D grounding is commonly formulated as candidate ranking, which requires precomputed instance proposals and becomes inefficient in large outdoor scenes. We propose Urbex, an agentic vision-language framework that instead casts grounding as active spatial search. Urbex represents a city-scale 3D scene as an interactive multi-view environment, allowing a VLM agent to query landmarks, zoom into local regions, render oblique views, and commit a grounded bounding box. We optimize this tool-use policy with reinforcement learning on CityRefer, using smooth localization rewards and lightwei",pdfUrl:"https://arxiv.org/pdf/2610.18356",primaryCategory:"cs.CV",published:"2026-10-13T00:00:00Z"},{id:"2610.18773",title:"Jeva: System One Models from First Principles",up:40,href:"https://arxiv.org/abs/2610.18773",abstract:"System one models enable direct, low-latency decision-making. Yet recent practice of predicting an answer from serialized text does not, by itself, respect the structure of a decision problem. We argue that current designs underemphasize four important structural requirements. (i) null-aware: Models should distinguish answer absence from uncertainty among candidates; (ii) permutation-invariant: Reordering alternatives should not change the decision; (iii) option-scalable: Growing candidate sets should not require redefining the output space; (iv) cacheable: Request-independent computation over",pdfUrl:"https://arxiv.org/pdf/2610.18773",primaryCategory:"cs.AI",published:"2026-10-13T00:00:00Z"},{id:"2610.16794",title:"TPPO: Tracking-Value PPO For Language Model Reasoning",up:36,href:"https://arxiv.org/abs/2610.16794",abstract:"Proximal Policy Optimization (PPO) is widely used in reinforcement learning with verifiable rewards for language-model reasoning. While \\emph{value evolution along trajectory} characterizes relative token-level credit, yet standard critics often fail to track it under sparse terminal rewards. To model this evolution, we analyze the relation between successive prefix values and show that they admit a Bayesian decomposition with additive updates in log-odds space. We use this additive structure to construct Tracking-Value PPO (\\method), a cumulative value parameterization that sums position-wise",pdfUrl:"https://arxiv.org/pdf/2610.16794",primaryCategory:"cs.LG",published:"2026-10-12T00:00:00Z"},{id:"2610.18615",title:"VideoJev: System One Model for Video Understanding and Interaction",up:36,href:"https://arxiv.org/abs/2610.18615",abstract:"Visual agents must turn video observations into timely decisions to track progress and choose what to do next. Building on the emerging System One paradigm, we introduce VideoJev, a family of models that cast video understanding and interaction as structured decision tasks. We adapt pretrained multimodal large language models (MLLMs) by replacing autoregressive answer decoding with a shared head that scores temporal intervals and textual options against video evidence. These scores yield event spans or answer choices, unifying temporal grounding and multiple-choice video question answering. Th",pdfUrl:"https://arxiv.org/pdf/2610.18615",primaryCategory:"cs.CV",published:"2026-10-13T00:00:00Z"},{id:"2609.38847",title:"Scoring Higher, Answering Worse: Mitigating Reward Hacking in Rubric-Based RL via Protocol-Level Rubrics",up:33,href:"https://arxiv.org/abs/2609.38847",abstract:"Rubric-based reinforcement learning (Rubric-RL) trains language models where no verifier exists. A judge checks each criterion of a rubric, and the verdicts are aggregated into a reward, most often by a weighted sum. We show that this additive aggregation is the weak point. Under a sum, criteria compensate for one another: a policy that misses the one decision that matters can buy the points back with advice nobody asked for. On clinical consultation, such a policy scores higher and answers worse. Rubric coverage rises while appropriateness on held-out physician criteria falls below the untrai",pdfUrl:"https://arxiv.org/pdf/2609.38847",primaryCategory:"cs.LG",published:"2026-09-30T00:00:00Z"},{id:"2610.17201",title:"Multics: Generative Multi-Player World Model with Hierarchical Communication",up:32,href:"https://arxiv.org/abs/2610.17201",abstract:"Multi-player interactive world models aim to simulate shared environments from multiple players' perspectives, but achieving robust generation while scaling to more players remains challenging. Existing approaches that rely on fully-connected communication (e.g., Solaris) incur quadratic attention costs as the number of players grows, while centralized approaches (e.g., $γ$-World) suffer from interference between unrelated events in a shared global representation. To address these challenges, we present Multics, a multi-player video generation framework with hierarchical communication that str",pdfUrl:"https://arxiv.org/pdf/2610.17201",primaryCategory:"cs.CV",published:"2026-10-12T00:00:00Z"},{id:"2610.01496",title:"SALD: Self-Referenced Advantage Learning for Diffusion Models",up:29,href:"https://arxiv.org/abs/2610.01496",abstract:"Recent work on language-model adaptation has shown that single models can obtain informative training signals by evaluating their behavior in demonstrationor feedback-augmented contexts, with the help of a teacher network, which is driven by the student's learned parameters. Inspired by this internal-reference principle, we investigate how diffusion models can identify self-referenced training signals without external demonstrations or teacher networks. We introduce SALD, a self-referenced training framework that evaluates each image-caption pair at two noise levels using the same model. The e",pdfUrl:"https://arxiv.org/pdf/2610.01496",primaryCategory:"cs.CV",published:"2026-10-07T00:00:00Z"},{id:"2610.17928",title:"Learning How to Remember: Memory Modality Selection for GUI Agents",up:27,href:"https://arxiv.org/abs/2610.17928",abstract:"Recent advances in vision-language models (VLMs) have substantially improved the capabilities of GUI agents, while memory augmentation has emerged as a promising approach for reusing knowledge from past interactions. However, existing memory augmented GUI agents typically adopt a fixed representation strategy, providing retrieved experience as a static modality. It remains unclear whether a single memory modality is consistently optimal, or how modality preference changes across interaction steps. In this work, we conduct a systematic study of memory modality in VLM based GUI agents. Across GU",pdfUrl:"https://arxiv.org/pdf/2610.17928",primaryCategory:"cs.AI",published:"2026-10-13T00:00:00Z"},{id:"2610.15166",title:"ExeWorldBench: Benchmarking Code-Based Executable 3D World Modeling",up:21,href:"https://arxiv.org/abs/2610.15166",abstract:"Coding agents are increasingly evolving beyond reproducing what a world looks like toward constructing executable worlds that capture how a world works. This shift calls for executable world modeling, which integrates two core capabilities: world understanding, reasoning about the underlying structural, mechanical, and causal principles of a world, and executable realization, translating that understanding into a code-based system whose behavior emerges from physical interactions. However, existing benchmarks provide only fragmented evaluations centered on physical reasoning, visual fidelity, ",pdfUrl:"https://arxiv.org/pdf/2610.15166",primaryCategory:"cs.CV",published:"2026-10-10T00:00:00Z"},{id:"2610.16811",title:"X-Ragent: Tool-Augmented Reinforcement Learning for Evidence-Grounded Chest X-Ray Reasoning",up:21,href:"https://arxiv.org/abs/2610.16811",abstract:"Chest X-ray (CXR) interpretation often requires integrating visual findings with task-specific evidence rather than relying on direct visual recognition alone. While tool-augmented medical agents can supply such evidence via external modules, they often lack explicit mechanisms for learning when auxiliary evidence is needed and for preventing inapplicable quantitative evidence from entering diagnostic reasoning. To address this, we propose X-Ragent, a post-training framework for tool-augmented reinforcement learning that decouples learned auxiliary-evidence seeking from validity-gated quantita",pdfUrl:"https://arxiv.org/pdf/2610.16811",primaryCategory:"cs.CV",published:"2026-10-12T00:00:00Z"},{id:"2610.18860",title:"AesCode: Aesthetic Code Generation with Decoupled Cross-Modal Rewards",up:19,href:"https://arxiv.org/abs/2610.18860",abstract:"Generating information-rich visual artifacts such as slides, posters, and dashboards as code is appealing because the outputs are structured, editable, and verifiable. Yet code models cannot see how their choices of layout and color come together on the canvas, often limiting spatial planning and aesthetic quality. Image generators excel at visual design but can misrender requested content, making their outputs unreliable targets for direct reproduction. We therefore introduce AesCode, which generates code grounded in the content prompt while using an image generated from the same prompt as an",pdfUrl:"https://arxiv.org/pdf/2610.18860",primaryCategory:"cs.AI",published:"2026-10-13T00:00:00Z"},{id:"2610.17953",title:"Agent-Reflex: Teaching Language Agents to Act Reflectively",up:16,href:"https://arxiv.org/abs/2610.17953",abstract:"Large language models have evolved from single-turn chatbots into interactive agents capable of long-horizon reasoning. In real deployments, MCP tool services can return noisy feedback and users may intervene to correct the agent, but existing methods provide limited supervision for reflection learning and failure recovery. To bridge this gap, we propose Agent-Reflex, a general training framework for incentivizing proactive reflection in agents. Specifically, Agent-Reflex comprises three stages. First, Environment Reflection Skill Discovery (RSD) injects grounded tool-feedback perturbations in",pdfUrl:"https://arxiv.org/pdf/2610.17953",primaryCategory:"cs.CL",published:"2026-10-13T00:00:00Z"},{id:"2610.17666",title:"DeltaTTG: Training Multi-Turn Agents with a Token-to-Go Progress Meter",up:15,href:"https://arxiv.org/abs/2610.17666",abstract:"Reinforcement learning with verifiable rewards (RLVR) for multi-turn agents relies on sparse terminal rewards that say little about individual steps. Within-group step comparisons depend on reliable state matching and sufficiently diverse sampled outcomes, while direct step scoring may require costly external evaluators, human annotations, or task-specific heuristics. We introduce DeltaTTG to learn a reusable progress signal through a shared progress meter, using low-cost supervision from diverse policies' recorded trajectories without task-specific progress rules. Its supervision target, Toke",pdfUrl:"https://arxiv.org/pdf/2610.17666",primaryCategory:"cs.LG",published:"2026-10-13T00:00:00Z"},{id:"2610.11850",title:"VEDJE: Video-Efficient Discriminative Joint Encoder for Scalable Video-Text Retrieval",up:14,href:"https://arxiv.org/abs/2610.11850",abstract:"Finding the right video often requires distinguishing similar scenes in which different events occur. Joint matching improves retrieval, but processing rich video representations for each query is costly. VEDJE compresses features within sampled frames while keeping their representations separate in a reusable cache. Feature-change prediction supplies an auxiliary training signal that improves retrieval from the compressed cache without adding work at query time. On MSR-VTT, MSVD, DiDeMo, and ActivityNet, VEDJE improves R@1 over matched first-stage retrievers in both retrieval directions. On M",pdfUrl:"https://arxiv.org/pdf/2610.11850",primaryCategory:"cs.CV",published:"2026-10-12T00:00:00Z"},{id:"2610.15765",title:"A Decade in a Day: Synthesizing Agent-Native Interfaces from Human-Oriented Software Evolution",up:14,href:"https://arxiv.org/abs/2610.15765",abstract:"Large language model agents are emerging as an important new class of users of desktop applications. However, existing desktop interfaces were designed for human end users or application developers, leaving agents to interpret visual controls or discover and compose low-level software operations. This mismatch can hinder even capable agents, yet it remains unclear what interface properties make desktop software easier for agents to use. To study this question, we treat software evolution as a natural source of interface variation and introduce DeskIF-Bench, a benchmark of 255 artifact-verified",pdfUrl:"https://arxiv.org/pdf/2610.15765",primaryCategory:"cs.SE",published:"2026-10-11T00:00:00Z"},{id:"2610.18872",title:"EgoExplorer: A Vision-Motion-Touch Observatory for Human Loco-Manipulation In Situ",up:14,href:"https://arxiv.org/abs/2610.18872",abstract:"Learning humanoid loco-manipulation from human demonstrations rests on observing how locomotion, posture, and object interaction evolve together as tasks unfold. Scaling collection across diverse environments, in turn, favors lightweight, portable capture systems. Yet, existing datasets provide only partial views of this coordination. Thus, we introduce EgoExplorer, a 100-hour vision-motion-touch observatory of human loco-manipulation built with a wearable system. With an emphasis on professional activities, its continuous recordings align egocentric video with reconstructed whole-body motion,",pdfUrl:"https://arxiv.org/pdf/2610.18872",primaryCategory:"cs.RO",published:"2026-10-13T00:00:00Z"},{id:"2610.14118",title:"ClawLoop: Self-Improving Agents via Harness-Native Training Loop",up:13,href:"https://arxiv.org/abs/2610.14118",abstract:"The rapid advancement of Large Language Models (LLMs) has driven their deployment toward general-purpose harness environments, where LLM-based agents operate in sandbox workspaces and interact directly with file systems and shells. While numerous post-training pipelines exist for tool-use agents, their counterparts for harness-based agents remain scarce and are predominantly one-shot and teacher-dependent: a stronger external model synthesizes tasks and collects trajectories, the target agent is trained once, and evaluation results are consumed by human researchers rather than fed back into th",pdfUrl:"https://arxiv.org/pdf/2610.14118",primaryCategory:"cs.AI",published:"2026-10-09T00:00:00Z"},{id:"2610.16577",title:"CineRecon: Benchmarking Frontier Models for Agentic Cinematic Reconstruction",up:13,href:"https://arxiv.org/abs/2610.16577",abstract:"Reconstructing reference videos as editable dynamic 3D scenes is an important path toward controllable video generation for filmmaking: these scenes provide modifiable, renderable visual proxies that enable explicit control over scene layout, subject actions, and camera behavior. To evaluate agents' ability to reconstruct editable dynamic 3D scenes from dynamic reference videos, we introduce CineRecon, a benchmark comprising 50 reference videos and 360 annotated evaluation clips. The reference videos span film, real-world footage, and games. Given a complete video, an agent uses tools to const",pdfUrl:"https://arxiv.org/pdf/2610.16577",primaryCategory:"cs.CV",published:"2026-10-12T00:00:00Z"},{id:"2610.17656",title:"Open-o3-Video-v2: Seek, Ground, and Reason with Verifiable Spatio-Temporal Evidence",up:13,href:"https://arxiv.org/abs/2610.17656",abstract:"Reliable video reasoning requires models to produce correct answers and expose supporting visual evidence. Open-o3-Video enables verifiable reasoning by embedding timestamps and object-level bounding boxes into reasoning traces, but is restricted to frames from an initial sparse sampler. We introduce Open-o3-Video-v2, which formulates video reasoning as a unified agentic evidencegrounded process. The model identifies missing information, acquires additional observations, grounds the moments and objects supporting its reasoning, and writes this evidence into the trajectory before continuing or ",pdfUrl:"https://arxiv.org/pdf/2610.17656",primaryCategory:"cs.CV",published:"2026-10-13T00:00:00Z"},{id:"2610.18484",title:"ReTerm: Recovery Training for Self-Improving Terminal Agents",up:11,href:"https://arxiv.org/abs/2610.18484",abstract:"Terminal agents have shown strong abilities in complex coding tasks. However, they often struggle to recover from errors during long-running execution (e.g., command errors, faulty implementations), eventually leading to task failures. To this end, we present ReTerm, a self-improving terminal agent trained by learning how to recover from its own failed terminal tasks. To support its training, we construct a customized data pipeline and produce ReTerm-10K, a high-quality dataset that provides effective recovery demonstrations for SFT cold start. Furthermore, we propose ReTerm-GRPO, an online RL",pdfUrl:"https://arxiv.org/pdf/2610.18484",primaryCategory:"cs.AI",published:"2026-10-13T00:00:00Z"},{id:"2610.18871",title:"Cepheid: Decoupling Scale from Structure for Cross-Family Motion Completion",up:11,href:"https://arxiv.org/abs/2610.18871",abstract:"Sparse-to-dense motion completion recovers dense mesh motion from sparse vertex displacements. Residual priors trained on one geometry family frequently fail to beat parameter-free harmonic extension off-family. Moreover, cross-family training meets a scaling barrier: residual amplitude varies by more than an order of magnitude across geometry families and collapses as observations become denser. Since this scale depends on unknown target motion, it cannot be measured directly at test time. We decouple residual structure from physical scale by learning a dimensionless prior, estimating amplitu",pdfUrl:"https://arxiv.org/pdf/2610.18871",primaryCategory:"cs.CV",published:"2026-10-13T00:00:00Z"},{id:"2610.14293",title:"GeoFix: Geometry Fixing for 4D Consistent Generation",up:10,href:"https://arxiv.org/abs/2610.14293",abstract:"Video diffusion models increasingly serve as priors for 4D generation, but the generated videos often lack geometric consistency. Recent approaches address this through post-training by designing geometric rewards, yet this can degrade texture and fine detail, requiring auxiliary appearance rewards and careful reward balancing. To address this challenge, we propose GeoFix, a unified framework that improves geometric consistency and visual quality with a single geometric reward, applicable to both training and inference-time reward alignment. Our reward measures cross-view depth consistency in ",pdfUrl:"https://arxiv.org/pdf/2610.14293",primaryCategory:"cs.CV",published:"2026-10-09T00:00:00Z"},{id:"2610.14726",title:"LightVAE: Towards Compact and Efficient Video Autoencoders",up:9,href:"https://arxiv.org/abs/2610.14726",abstract:"Latent diffusion models enable high-quality video generation, but video VAE encoding and decoding remain computationally expensive. Existing methods use stage-specific lightweight operators, yet either constrain spatial and temporal computation jointly or remove temporal computation altogether, without distinguishing their compression sensitivities in pretrained Conv3D. To address these limitations, we present LightVAE, a compression framework that exploits redundancy in temporal modeling and network depth. LightVAE exactly reparameterizes eligible causal Conv3D layers into an aggregate spatia",pdfUrl:"https://arxiv.org/pdf/2610.14726",primaryCategory:"cs.CV",published:"2026-10-10T00:00:00Z"},{id:"2610.18868",title:"Tev: Scaling Long-Horizon Agentic Environments with Dense Progress Rewards",up:9,href:"https://arxiv.org/abs/2610.18868",abstract:"Long-horizon agents have drawn growing attention for their ability to work autonomously -- from hours to days -- on economically valuable tasks, a capability essential to automated discovery and recursive self-improvement (RSI). Yet open-source models still struggle on long-horizon tasks, largely for lack of both training data and a working recipe, and scaling both is hard: long, complex tasks are difficult to curate and verify, and their rewards are sparse. We address both. First, we introduce Tev-Gym, the first long-horizon agent training dataset with verifiable, dense, progressive rewards -",pdfUrl:"https://arxiv.org/pdf/2610.18868",primaryCategory:"cs.CL",published:"2026-10-13T00:00:00Z"},{id:"W4393160747",title:"ExpeL: LLM Agents Are Experiential Learners",up:0,href:"https://doi.org/10.1609/aaai.v38i17.29936",doi:"https://doi.org/10.1609/aaai.v38i17.29936",year:2024,openalexId:"https://openalex.org/W4393160747"},{id:"W4412877164",title:"Evaluation and Benchmarking of LLM Agents: A Survey",up:0,href:"https://doi.org/10.1145/3711896.3736570",crossrefDoi:"https://doi.org/10.1145/3711896.3736570",year:2025,openalexId:"https://openalex.org/W4412877164",crossrefIssued:"2025-08-03"},{id:"W4407759090",title:"A-Mem: Agentic Memory for LLM Agents",up:0,href:"https://doi.org/10.52202/085713-0593",doi:"https://doi.org/10.52202/085713-0593",year:2025,openalexId:"https://openalex.org/W4407759090"}]}}]);